changeSet.sql:
-- note.position moves to the placement (note_sentence.position);
-- the column stays until 057 but nothing writes it any more.
ALTER TABLE note ALTER COLUMN position DROP NOT NULL;

ALTER TABLE note_version ALTER COLUMN sentence_id DROP NOT NULL;
ALTER TABLE note_version ALTER COLUMN origin_sentence_id DROP NOT NULL;
ALTER TABLE note_version ALTER COLUMN origin_commit_hash DROP NOT NULL;
ALTER TABLE note_version DROP CONSTRAINT IF EXISTS fk_note_version_sentence;
ALTER TABLE note_version ADD CONSTRAINT fk_note_version_sentence
    FOREIGN KEY (sentence_id) REFERENCES sentence(sentence_id) ON DELETE SET NULL;

CREATE OR REPLACE FUNCTION note_legacy_home_mirror() RETURNS trigger AS $fn$
BEGIN
    IF NEW.sentence_id IS NOT NULL
       AND (TG_OP = 'INSERT' OR NEW.sentence_id IS DISTINCT FROM OLD.sentence_id) THEN
        INSERT INTO note_sentence (note_id, sentence_id, position, origin_sentence_id, origin_migration_id,
                                   origin_commit_hash, created_by)
        SELECT NEW.note_id, NEW.sentence_id, NEW.position, NEW.sentence_id, s.migration_id, s.commit_hash, NEW.user_id
        FROM (SELECT NEW.sentence_id) AS x
        LEFT JOIN sentence s ON s.sentence_id = NEW.sentence_id
        ON CONFLICT (note_id, sentence_id) DO NOTHING;
    END IF;
    IF TG_OP = 'INSERT' AND NEW.scratchpad_id IS NOT NULL THEN
        INSERT INTO note_scratchpad (note_id, scratchpad_id)
        VALUES (NEW.note_id, NEW.scratchpad_id)
        ON CONFLICT (note_id, scratchpad_id) DO NOTHING;
    END IF;
    RETURN NULL;
END
$fn$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_note_legacy_home_mirror ON note;
CREATE TRIGGER trg_note_legacy_home_mirror
    AFTER INSERT OR UPDATE OF sentence_id ON note
    FOR EACH ROW EXECUTE FUNCTION note_legacy_home_mirror();
